-- Isolated guide CMS. Existing applications, profiles and public text are preserved.
begin;
create table if not exists technician_private.guide_cms_state_v1(singleton boolean primary key default true check(singleton),draft jsonb not null,published jsonb not null,version bigint not null default 1 check(version>0),updated_at timestamptz not null default now());
create table if not exists technician_private.guide_cms_revisions_v1(id uuid primary key default gen_random_uuid(),version bigint not null unique,content jsonb not null,action text not null check(action in('original','publish','restore')),operator_id uuid,created_at timestamptz not null default now());
create table if not exists technician_private.guide_cms_commands_v1(operation_id uuid primary key,operator_id uuid not null,request_digest text not null,action text not null,applied_version bigint not null,created_at timestamptz not null default now());
alter table technician_private.guide_cms_state_v1 enable row level security;
alter table technician_private.guide_cms_revisions_v1 enable row level security;
alter table technician_private.guide_cms_commands_v1 enable row level security;
revoke all on technician_private.guide_cms_state_v1,technician_private.guide_cms_revisions_v1,technician_private.guide_cms_commands_v1 from public,anon,authenticated,service_role;
grant select,insert,update on technician_private.guide_cms_state_v1 to service_role;
grant select,insert on technician_private.guide_cms_revisions_v1,technician_private.guide_cms_commands_v1 to service_role;
create or replace function technician_private.guide_cms_metadata_v1() returns jsonb language sql immutable set search_path=pg_catalog as $$select '[{"id":"t001","group":"섹션 제목·안내","label":"섹션 제목","value":"집수리, 이렇게 준비하세요","maxLength":60},{"id":"t002","group":"섹션 제목·안내","label":"안내 문구","value":"문의 방법부터 비용 확인까지, 필요한 내용을 한눈에 확인하세요.","maxLength":240},{"id":"t003","group":"이용 순서 4단계","label":"안내 제목","value":"수리 분야 선택","maxLength":60},{"id":"t004","group":"이용 순서 4단계","label":"안내 문구","value":"필요한 작업 선택","maxLength":240},{"id":"t005","group":"이용 순서 4단계","label":"안내 제목","value":"전문가 확인","maxLength":60},{"id":"t006","group":"이용 순서 4단계","label":"안내 문구","value":"전문 분야·출장 지역 확인","maxLength":240},{"id":"t007","group":"이용 순서 4단계","label":"안내 제목","value":"직접 상담","maxLength":60},{"id":"t008","group":"이용 순서 4단계","label":"안내 문구","value":"증상·방문 가능 여부 문의","maxLength":240},{"id":"t009","group":"이용 순서 4단계","label":"안내 제목","value":"비용·일정 협의","maxLength":60},{"id":"t010","group":"이용 순서 4단계","label":"안내 문구","value":"작업 범위·금액·일정 확인","maxLength":240},{"id":"t011","group":"섹션 제목·안내","label":"안내 문구","value":"실제 상담은 전문가 연락 수단 제공 후 이용할 수 있습니다.","maxLength":240},{"id":"t012","group":"비용 안내","label":"안내 제목","value":"수리 비용, 작업 전에 확인하세요","maxLength":60},{"id":"t013","group":"비용 안내","label":"안내 문구","value":"작업 전 미리 확인하면, 더 원활한 상담이 가능합니다.","maxLength":240},{"id":"t014","group":"비용 안내","label":"항목 제목","value":"출장·진단비","maxLength":60},{"id":"t015","group":"비용 안내","label":"안내 문구","value":"수리하지 않아도 비용이 있는지","maxLength":240},{"id":"t016","group":"비용 안내","label":"항목 제목","value":"작업비","maxLength":60},{"id":"t017","group":"비용 안내","label":"안내 문구","value":"어떤 작업이 포함되는지","maxLength":240},{"id":"t018","group":"비용 안내","label":"항목 제목","value":"부품·자재비","maxLength":60},{"id":"t019","group":"비용 안내","label":"안내 문구","value":"포함인지 별도인지","maxLength":240},{"id":"t020","group":"비용 안내","label":"안내 문구","value":"추가 작업은 내용과 금액을 확인한 뒤 결정하세요.","maxLength":240},{"id":"t021","group":"문의 준비 제목","label":"안내 제목","value":"문의 전에 무엇을 준비할까요?","maxLength":60},{"id":"t022","group":"문의 준비 제목","label":"안내 문구","value":"필요한 항목을 눌러 확인하세요.","maxLength":240},{"id":"t023","group":"문의 준비 1","label":"펼침 제목","value":"문제 위치와 증상","maxLength":60},{"id":"t024","group":"문의 준비 1","label":"준비 항목","value":"어느 공간인가요? — 주방·욕실·거실 등","maxLength":240},{"id":"t025","group":"문의 준비 1","label":"준비 항목","value":"어느 부분인가요? — 싱크대·수도꼭지·벽 등","maxLength":240},{"id":"t026","group":"문의 준비 1","label":"준비 항목","value":"언제부터 문제가 생겼나요?","maxLength":240},{"id":"t027","group":"문의 준비 1","label":"준비 항목","value":"어떤 모습인가요? — 물이 떨어져요·젖어 있어요 등","maxLength":240},{"id":"t028","group":"문의 준비 1","label":"예시 제목","value":"설명 예시","maxLength":60},{"id":"t029","group":"문의 준비 1","label":"안내 문구","value":"주방 싱크대 아래에서 물이 떨어져요.","maxLength":240},{"id":"t030","group":"문의 준비 1","label":"안내 문구","value":"어제부터 물을 사용할 때 생깁니다.","maxLength":240},{"id":"t031","group":"문의 준비 1","label":"안내 문구","value":"원인을 몰라도 보이는 증상만 알려주세요.","maxLength":240},{"id":"t032","group":"문의 준비 2","label":"펼침 제목","value":"전체 모습과 문제 부위 사진","maxLength":60},{"id":"t033","group":"문의 준비 2","label":"사진 설명","value":"전체 사진 · 연출 예시","maxLength":60},{"id":"t034","group":"문의 준비 2","label":"사진 설명","value":"가까운 사진 · 연출 예시","maxLength":60},{"id":"t035","group":"문의 준비 2","label":"준비 항목","value":"주변이 보이는 전체 사진 한 장","maxLength":240},{"id":"t036","group":"문의 준비 2","label":"준비 항목","value":"문제 부위를 가까이 찍은 사진 한 장","maxLength":240},{"id":"t037","group":"문의 준비 2","label":"준비 항목","value":"흐리거나 어두우면 다시 촬영","maxLength":240},{"id":"t038","group":"문의 준비 2","label":"안내 문구","value":"집 주소·얼굴 등 불필요한 개인정보가 보이지 않게 확인하세요.","maxLength":240},{"id":"t039","group":"문의 준비 3","label":"펼침 제목","value":"방문 지역과 희망 일정","maxLength":60},{"id":"t040","group":"문의 준비 3","label":"준비 항목","value":"부산 구·군과 동·읍·면","maxLength":240},{"id":"t041","group":"문의 준비 3","label":"준비 항목","value":"가능한 날짜·시간을 두 가지 정도","maxLength":240},{"id":"t042","group":"문의 준비 3","label":"준비 항목","value":"일정 협의 가능 여부","maxLength":240},{"id":"t043","group":"문의 준비 3","label":"준비 항목","value":"주차·출입·작업 공간 등 현장 조건","maxLength":240},{"id":"t044","group":"문의 준비 3","label":"예시 제목","value":"전달 예시","maxLength":60},{"id":"t045","group":"문의 준비 3","label":"안내 문구","value":"해운대구 좌동 / 평일 오후 또는 토요일 오전 / 일정 협의 가능","maxLength":240},{"id":"t046","group":"문의 준비 3","label":"안내 문구","value":"상세 주소는 방문을 협의할 때 전달하세요.","maxLength":240},{"id":"t047","group":"문의 준비 3","label":"안내 문구","value":"희망 일정은 예약 확정이 아닙니다.","maxLength":240}]'::jsonb$$;
create or replace function technician_private.guide_cms_original_v1() returns jsonb language sql immutable set search_path=pg_catalog,technician_private as $$select jsonb_object_agg(f->>'id',f->'value') from jsonb_array_elements(technician_private.guide_cms_metadata_v1()) f$$;
insert into technician_private.guide_cms_state_v1(singleton,draft,published) values(true,technician_private.guide_cms_original_v1(),technician_private.guide_cms_original_v1()) on conflict do nothing;
insert into technician_private.guide_cms_revisions_v1(version,content,action) select 1,technician_private.guide_cms_original_v1(),'original' where not exists(select 1 from technician_private.guide_cms_revisions_v1);
create or replace function technician_private.guide_cms_validate_v1(content jsonb) returns void language plpgsql security invoker set search_path=pg_catalog,technician_private as $$declare f jsonb;begin
 if jsonb_typeof(content) is distinct from 'object' then raise exception 'invalid guide object';end if;
 if (select count(*) from jsonb_object_keys(content))<>47 then raise exception 'invalid guide keys';end if;
 for f in select * from jsonb_array_elements(technician_private.guide_cms_metadata_v1()) loop
 if jsonb_typeof(content->(f->>'id')) is distinct from 'string' or length(btrim(content->>(f->>'id'))) not between 1 and (f->>'maxLength')::integer or content->>(f->>'id') ~ '[[:cntrl:]]' then raise exception 'invalid guide text';end if;
 end loop;end;$$;
create or replace function technician_private.guide_cms_snapshot_v1() returns jsonb language sql stable security invoker set search_path=pg_catalog,technician_private as $$select jsonb_build_object('draft',s.draft,'published',s.published,'version',s.version,'fields',technician_private.guide_cms_metadata_v1(),'revisions',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'version',r.version,'content',r.content,'action',r.action,'date',r.created_at) order by r.version desc) from(select * from technician_private.guide_cms_revisions_v1 order by version desc limit 100)r),'[]'::jsonb)) from technician_private.guide_cms_state_v1 s where singleton$$;
create or replace function public.technician_guide_cms_v1(op text,p jsonb default '{}'::jsonb) returns jsonb language plpgsql security invoker set search_path=pg_catalog,technician_private as $$
declare s technician_private.sessions%rowtype; current_state technician_private.guide_cms_state_v1%rowtype;command technician_private.guide_cms_commands_v1%rowtype;command_id uuid;chosen jsonb;begin
 if op='published' then return(select jsonb_build_object('content',published,'version',(select max(version) from technician_private.guide_cms_revisions_v1)) from technician_private.guide_cms_state_v1 where singleton);end if;
 s=technician_private.require_admin_v2(p->>'hash');
 if op='state' then return technician_private.guide_cms_snapshot_v1();end if;
 if op not in('draft','publish','restore') then raise exception 'invalid guide operation';end if;
 if coalesce(p->>'operationId','') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' or coalesce(p->>'requestDigest','') !~ '^[a-f0-9]{64}$' then raise exception 'invalid guide command';end if;
 command_id=(p->>'operationId')::uuid;perform pg_advisory_xact_lock(hashtextextended(command_id::text,9110));
 select * into current_state from technician_private.guide_cms_state_v1 where singleton for update;
 if not found then raise exception 'not found';end if;
 select * into command from technician_private.guide_cms_commands_v1 where operation_id=command_id;
 if found then if command.operator_id<>s.admin_id or command.request_digest is distinct from p->>'requestDigest' or command.action<>op then raise exception 'command conflict';end if;return technician_private.guide_cms_snapshot_v1();end if;
 if coalesce(p->>'version','') !~ '^[0-9]{1,15}$' or (p->>'version')::bigint<>current_state.version then raise exception 'version conflict';end if;
 if op='draft' then chosen=p->'content';perform technician_private.guide_cms_validate_v1(chosen);update technician_private.guide_cms_state_v1 set draft=chosen,version=version+1,updated_at=now() where singleton returning * into current_state;
 else
 if op='publish' then if p->'reviewed' is distinct from 'true'::jsonb or p->>'reviewedVersion' is distinct from p->>'version' then raise exception 'invalid guide review';end if;chosen=current_state.draft;
 else select content into chosen from technician_private.guide_cms_revisions_v1 where id=(p->>'revisionId')::uuid;if not found then raise exception 'not found';end if;end if;
 perform technician_private.guide_cms_validate_v1(chosen);update technician_private.guide_cms_state_v1 set draft=chosen,published=chosen,version=version+1,updated_at=now() where singleton returning * into current_state;
 insert into technician_private.guide_cms_revisions_v1(version,content,action,operator_id)values(current_state.version,chosen,op,s.admin_id);
 end if;
 insert into technician_private.guide_cms_commands_v1(operation_id,operator_id,request_digest,action,applied_version)values(command_id,s.admin_id,p->>'requestDigest',op,current_state.version);
 insert into technician_private.admin_activity(operator_id,target,action)values(s.admin_id,'home-guide','guide-'||case op when 'draft' then 'draft-save' else op end);
 update technician_private.sessions set last_active_at=now() where hash=s.hash;
 return technician_private.guide_cms_snapshot_v1();end;$$;
revoke all on function technician_private.guide_cms_metadata_v1(),technician_private.guide_cms_original_v1(),technician_private.guide_cms_validate_v1(jsonb),technician_private.guide_cms_snapshot_v1(),public.technician_guide_cms_v1(text,jsonb) from public,anon,authenticated;
grant execute on function technician_private.guide_cms_metadata_v1(),technician_private.guide_cms_original_v1(),technician_private.guide_cms_validate_v1(jsonb),technician_private.guide_cms_snapshot_v1(),public.technician_guide_cms_v1(text,jsonb) to service_role;
commit;
